#!/usr/bin/env python3
"""Researched roster of characters in Assam's history, c. 350 CE to 1826 (Kamarupa rulers come from
data/sources/Assam_Dynasties_Chronological_Timeline.csv; everything else is defined here).

Writes data/research/characters_pre1826.json. Each entry carries sources and a confidence level
(high = several sources agree, medium = one good source, low = single/uncertain/legendary source).
Edit this file to correct or extend, then run:  python3 tools/research_pre1826.py && python3 tools/merge_research.py
"""
import json
from pathlib import Path

