E("singhadhwaj","Singhadhwaj","Kamata and Khen kingdoms",1280,1290,"13th–14th century (dates not given)","King of Kamata","Kamata ruler whose minister Pratapdhwaj later took power.","",("kamata",),"low",sort=1282)
E("pratapdhwaj","Pratapdhwaj","Kamata and Khen kingdoms",1290,1300,"c. 1300 (dates not given)","Minister who became king","Minister of Singhadhwaj who took the Kamata throne; father of Durlabhnarayan.","",("kamata",),"low",sort=1292)
E("dharmanarayan","Dharmanarayan","Kamata and Khen kingdoms",1295,1305,"c. 1300 (dates not given)","Kamata ruler","Cousin of Pratapdhwaj who seized power at his death; after a settlement he kept Rangpur and Mymensingh.","",("kamata",),"low",sort=1296)

# ---------------------------------------------------------------- Ahom kings
E("sukaphaa","Chaolung Sukaphaa","Ahom kings",1228,1268,"1228–1268","First Ahom king","Born around 1189 in Mong Mao, he left in 1215, crossed the Patkai hills and reached Namrup in December 1228, founding the Ahom kingdom that lasted until 1826. He built Charaideo in 1253.","Married daughters of the Moran chief Badaucha and the Barahi chief Thakumatha. Moved his base from 1236 (Mungklang) through Habung (1240) and Ligirigaon (1244) before Charaideo.",("sukapha","ahomdyn"),"high",("Chaolung Sukaphaa","Chaolung Sukapha"),"চাওলুং সুকাফা",birth=1189,death=1268)
E("suteuphaa","Suteuphaa","Ahom kings",1268,1281,"1268–1281","Second Ahom king","Son of Sukaphaa; died a natural death.","Catalogued scenes cover the Dikhou frontier with the Kacharis and the Naga hill campaigns.",("ahomdyn","catalog"),"medium",("Suteuphaa",),"সুতেউফা")
E("subinphaa","Subinphaa","Ahom kings",1281,1293,"1281–1293","Third Ahom king","Son of Suteuphaa; set up the Satghariya Ahom group and died naturally.","",("ahomdyn","catalog"),"medium",("Subinphaa",),"সুবিনফা")
E("sukhaangphaa","Sukhaangphaa","Ahom kings",1293,1332,"1293–1332","Fourth Ahom king","Son of Subinphaa. His long war with the Kamata king (from about 1324) ended in a truce sealed by marrying the Kamata princesses Rajani and Bhajani.","The king list gives a natural death, but a footnote says he was deposed and executed.",("sukhaang","ahomdyn"),"medium",("Sukhangphaa","Sukhaangphaa"),"সুখাংফা")
E("sukhrangphaa","Sukhrangphaa","Ahom kings",1332,1364,"1332–1364","Fifth Ahom king","Son of Sukhaangphaa; created the post of Charing Raja. His death was followed by an interregnum (1364–1369).","",("ahomdyn","catalog"),"medium",("Sukhrangphaa",),"সুখ্ৰাংফা")
E("sutuphaa","Sutuphaa","Ahom kings",1369,1376,"1369–1376","Sixth Ahom king","Brother of Sukhrangphaa; assassinated. Another interregnum (1376–1380) followed.","",("ahomdyn","catalog"),"medium",("Sutuphaa",),"সুতুফা")
E("tyao-khamti","Tyao Khamti","Ahom kings",1380,1389,"1380–1389","Seventh Ahom king","Brother of Sutuphaa; assassinated by nobles in 1389 (a family tree gives 1387). He led an unsuccessful expedition against the Chutias.","Followed by an interregnum until 1397.",("ahomdyn","chutia","sudang"),"medium",("Tyao Khamti",),"ত্যাও খামতি")
E("sudangphaa","Sudangphaa (Bamuni Konwar)","Ahom kings",1397,1407,"1397–1407","Eighth Ahom king","Son of Tyao Khamti, raised by a Brahmin family in Habung after his mother's execution; found and enthroned at about fifteen in 1397. He introduced the Singarigharutha coronation (1403) and let Hindu rites into the court.","Peace treaty fixing the Patkai boundary in 1401; capital moved to Charguwa in 1403.",("sudang","ahomdyn"),"high",("Sudangphaa",),"সুদাংফা (বামুনী কোঁৱৰ)")
E("sujangphaa","Sujangphaa","Ahom kings",1407,1422,"1407–1422","Ninth Ahom king","Son of Sudangphaa; died naturally.","",("ahomdyn","catalog"),"medium",("Sujanphaa","Sujangphaa"),"সুজাংফা")
E("suphakphaa","Suphakphaa","Ahom kings",1422,1439,"1422–1439","Tenth Ahom king","Son of Sujangphaa; died naturally.","",("ahomdyn","catalog"),"medium",("Suphakphaa",),"সুফাকফা")
E("susenphaa","Susenphaa","Ahom kings",1439,1488,"1439–1488","Eleventh Ahom king","Son of Suphakphaa; reigned about half a century and built a temple at Negheriting.","Catalogued scenes cover a long peace and the Tangshu expedition.",("ahomdyn","catalog"),"medium",("Susenphaa",),"সুচেনফা")
E("suhenphaa","Suhenphaa","Ahom kings",1488,1493,"1488–1493","Twelfth Ahom king","Son of Susenphaa; speared to death in his palace.","",("ahomdyn","catalog"),"medium",("Suhenphaa",),"সুহেনফা")
E("supimphaa","Supimphaa","Ahom kings",1493,1497,"1493–1497","Thirteenth Ahom king","Son of Suhenphaa; died naturally. A catalogued scene shows him trying his father's killers.","",("ahomdyn","catalog"),"medium",("Supimphaa",),"সুপিম্ফা")
E("suhungmung","Suhungmung (Swarganarayan)","Ahom kings",1497,1539,"1497–1539","Fourteenth Ahom king","Expanded the kingdom for the first time since Sukaphaa, annexing Chutia and Dimasa territory and repelling the Bengal invasions of 1527 and 1532–33. First Ahom king to take a Hindu title, Swarganarayan.","Annexed Habung 1512; Chutia kingdom 1523–24; created the Borpatragohain post 1527; killed in his sleep in 1539 by his servant Ratiman.",("suhung","ahomdyn"),"high",("Suhungmung",),"সুহুংমুং")
E("suklenmung","Suklenmung (Garhgayan Roja)","Ahom kings",1539,1552,"1539–1552","Fifteenth Ahom king","Made Garhgaon the capital and drove the Koch army off the north bank in 1546. In his reign Hari, Sankardev's son-in-law, was executed, leading Sankardev to leave the kingdom.","Some chronicles suspected him in his father's murder.",("suklen","ahomdyn"),"high",("Suklenmung",),"সুক্লেনমুং")
E("sukhaamphaa","Sukhaamphaa (Khora Roja)","Ahom kings",1552,1603,"1552–1603","Sixteenth Ahom king","Longest-reigning Ahom king (about 51 years). Chilarai's 1563 invasion forced the Treaty of Majuli. The Ekasarana faith took firm root in his reign.","Nicknamed Khora Roja after a limp from an elephant fall.",("sukhaam","ahomdyn"),"high",("Sukhaamphaa","Sukhaamphaa Khora Raja"),"সুখাম্ফা (খোৰা ৰজা)")
E("pratap-singha","Pratap Singha (Susenghphaa)","Ahom kings",1603,1641,"1603–1641","Seventeenth Ahom king","Created the Borbarua and Borphukan offices, reorganised the paik system through Momai Tamuli Borbarua, and fought the first Mughal wars.","Also known as Burha Roja and Buddhiswarganarayan. Married Mangaldahi, daughter of Parikshit Narayan, in 1608.",("pratap","ahomdyn"),"high",("Pratap Singha",),"প্ৰতাপ সিংহ")
E("suramphaa","Suramphaa (Jayaditya Singha, Bhoga Roja)","Ahom kings",1641,1644,"1641–1644","Eighteenth Ahom king","Son of Pratap Singha; deposed in 1644 and later murdered.","",("ahomdyn","catalog"),"medium",("Suramphaa",),"সুৰম্ফা (ভোগা ৰজা)")
E("sutingphaa","Sutingphaa (Noriya Roja)","Ahom kings",1644,1648,"1644–1648","Nineteenth Ahom king","Brother of Suramphaa; deposed by the Burhagohain in 1648 and later murdered.","",("ahomdyn","jayad"),"medium",("Sutingphaa","Sutingphaa Noriya Raja"),"সুটিংফা (নৰীয়া ৰজা)")
E("jayadhwaj-singha","Jayadhwaj Singha (Sutamla)","Ahom kings",1648,1663,"1648–1663","Twentieth Ahom king","Drove the Mughals from Guwahati in 1648. Mir Jumla took Garhgaon in March 1662; the king withdrew to Namrup and signed the Treaty of Ghilajharighat in January 1663. A patron of Vaishnava satras.","Called Bhagania Roja (“the fugitive”). Struck the first coins in his name.",("jayad","amc","ahomdyn"),"high",("Jayadhwaj Singha","Sutamla"),"জয়ধ্বজ সিংহ")
E("chakradhwaj-singha","Chakradhwaj Singha (Supangmung)","Ahom kings",1663,1670,"1663–1670","Twenty-first Ahom king","Refused Mughal tribute, rebuilt the army and recaptured Guwahati in 1667. Appointed Atan Burhagohain Rajmantri Dangaria and Lachit Borphukan commander.","Died April 1670.",("amc","atan","ahomdyn"),"high",("Chakradhwaj Singha",),"চক্ৰধ্বজ সিংহ")
E("udayaditya-singha","Udayaditya Singha (Sunyatphaa)","Ahom kings",1670,1672,"1670–1672","Twenty-second Ahom king","Brother of Chakradhwaj; renewed the war with the Mughals and ordered Lachit to Saraighat. Deposed and executed.","",("amc","ahomdyn"),"high",("Udayaditya Singha",),"উদয়াদিত্য সিংহ")
E("ramdhwaj-singha","Ramdhwaj Singha (Suklamphaa)","Ahom kings",1672,1674,"1672–1674","Twenty-third Ahom king","Brother of Udayaditya; poisoned in 1674 during court intrigue.","",("ahomdyn","catalog"),"medium",("Ramdhwaj Singha",),"ৰামধ্বজ সিংহ")
E("suhung","Suhung (Samaguria Roja)","Ahom kings",1674,1675,"1674–1675","Twenty-fourth Ahom king","Raised to the throne by Debera Borbarua and deposed after about 21 days.","",("ahomdyn","catalog"),"medium",("Suhung","Samaguria Raja"),"সমগুৰিয়া ৰজা")
E("gobar-roja","Gobar Roja","Ahom kings",1675,1675,"1675 (about 24 days)","Twenty-fifth Ahom king","A puppet king under Debera Borbarua, deposed and executed after about 24 days.","Father of Gadadhar Singha.",("ahomdyn","gadad"),"medium",("Gobar Raja",),"গোবৰ ৰজা")
E("sujinphaa","Sujinphaa (Arjun Konwar)","Ahom kings",1675,1677,"1675–1677","Twenty-sixth Ahom king","Grandson of Pratap Singha, installed by Atan Burhagohain; deposed and died by suicide.","",("ahomdyn","atan"),"medium",("Sujinphaa",),"সুজিনফা")
E("sudoiphaa","Sudoiphaa (Parvatia Roja)","Ahom kings",1677,1679,"1677–1679","Twenty-seventh Ahom king","King during the 1679 conspiracy that led to the murder of Atan Burhagohain; deposed and killed.","",("ahomdyn","amc"),"medium",("Sudoiphaa",),"সুদইফা (পৰ্বতীয়া ৰজা)")
E("sulikphaa","Sulikphaa (Ratnadhwaj Singha, Lora Roja)","Ahom kings",1679,1681,"1679–1681","Twenty-eighth Ahom king","A boy king under Laluk Sola Borphukan; deposed and killed. A rule that claimants must be physically unblemished was introduced in his reign.","",("ahomdyn","gadad"),"medium",("Sulikphaa","Sulikphaa Lora Raja"),"সুলিকফা (লোৰা ৰজা)")
E("gadadhar-singha","Gadadhar Singha (Supaatphaa)","Ahom kings",1681,1696,"1681–1696","Twenty-ninth Ahom king","Founder of the Tungkhungia line. Came out of exile in the Naga hills to take the throne in 1681 and retook Guwahati at Itakhuli in 1682, ending the Ahom–Mughal wars.","Husband of Joymoti Konwari. Built the Dhodar Ali road and began a land survey.",("gadad","ahomdyn"),"high",("Gadadhar Singha","Prince Gadapani"),"গদাধৰ সিংহ")
E("rudra-singha","Rudra Singha (Sukhrungphaa)","Ahom kings",1696,1714,"1696–1714","Thirtieth Ahom king","Took the kingdom to its peak, founded Rangpur as the capital, campaigned against the Dimasa and Jaintia kingdoms (1706–08) and planned a great war on Mughal Bengal, dying before it began.","Born c. 1665; died 27 August 1714 at North Guwahati.",("rudra","ahomdyn"),"high",("Rudra Singha",),"ৰুদ্ৰ সিংহ")
E("siva-singha","Siva Singha (Sutanphaa)","Ahom kings",1714,1744,"1714–1744","Thirty-first Ahom king","A devout Shakta who gave land to temples and Brahmins and shared royal authority with his queens, who ruled in turn as Bar Raja. A golden age of Assamese manuscripts.","",("siva","ahomdyn"),"high",("Siva Singha",),"শিৱ সিংহ")
E("pramatta-singha","Pramatta Singha (Sunenphaa)","Ahom kings",1744,1751,"1744–1751","Thirty-second Ahom king","Brother of Siva Singha; died naturally. Catalogued scenes show Rang Ghar games in his reign.","",("ahomdyn","catalog"),"medium",("Pramatta Singha",),"প্ৰমত্ত সিংহ")
E("rajeswar-singha","Rajeswar Singha (Suremphaa)","Ahom kings",1751,1769,"1751–1769","Thirty-third Ahom king","Fourth son of Rudra Singha. Sheltered Bhagyachandra of Manipur, sent the failed 1765 expedition, and married Kuranganayani in 1768. Much of the governing fell to Kirti Chandra Borbarua.","Died at Dergaon in 1769. Added three underground storeys to the Kareng Ghar (Talatal Ghar).",("rajes","ahomdyn","kuran"),"high",("Rajeswar Singha",),"ৰাজেশ্বৰ সিংহ")
E("lakshmi-singha","Lakshmi Singha (Sunyeophaa)","Ahom kings",1769,1780,"1769–1780","Thirty-fourth Ahom king","Made king by Kirti Chandra Borbarua. The Moamoria rebellion began in 1769 and the rebels captured him; royalists restored him in 1770.","Died 13 December 1780.",("laksh","moam","ahomdyn"),"high",("Lakshmi Singha",),"লক্ষ্মী সিংহ")
E("gaurinath-singha","Gaurinath Singha (Suhitpangphaa)","Ahom kings",1780,1795,"1780–1795","Thirty-fifth Ahom king","Became king at about fifteen. Rebels took the capital in 1786; British troops under Captain Welsh restored order in lower Assam in 1792–94 and then left. Died at Jorhat in December 1794.","The infobox gives 1794 as the end; the king list gives 1795.",("gauri","moam","ahomdyn"),"high",("Gaurinath Singha",),"গৌৰীনাথ সিংহ")
E("kamaleswar-singha","Kamaleswar Singha (Suklingphaa)","Ahom kings",1795,1811,"1795–1811","Thirty-sixth Ahom king","Placed on the throne as an infant by Purnananda Burhagohain, who held real power; died of smallpox.","",("gauri","ahomdyn"),"high",("Kamaleswar Singha",),"কমলেশ্বৰ সিংহ")
E("chandrakanta-singha","Chandrakanta Singha (Sudingphaa)","Ahom kings",1811,1821,"1811–1818, 1819–1821","Thirty-seventh Ahom king","Named king at about fourteen by Purnananda Burhagohain. Deposed in 1818, reinstalled by the Burmese in 1819, defeated in 1822 and fled to British territory. Died in Guwahati in 1839.","Born c. 1797. After Yandabo he received a pension of 500 rupees.",("chandra","burm","ahomdyn"),"high",("Chandrakanta Singha",),"চন্দ্ৰকান্ত সিংহ",birth=1797,death=1839)
E("purandar-singha","Purandar Singha","Ahom kings",1818,1819,"1818–1819, 1833–1838","Thirty-eighth Ahom king","Installed as a boy in 1818 by Ruchinath Burhagohain, lost the throne to the Burmese in 1819, and was made a tributary prince by the British in 1833. Deposed in September 1838.","Born 1807, died 1 October 1846 at Jorhat. Also called Suremphaa II.",("purandar","ahomdyn","burm"),"high",("Purandar Singha",),"পুৰন্দৰ সিংহ",birth=1807,death=1846)
E("jogeswar-singha","Jogeswar Singha","Ahom kings",1821,1822,"1821–1822","Thirty-ninth Ahom king","A puppet king installed by the Burmese commander Mingimaha Tilwa in 1821; removed in 1822.","",("ahomdyn","burm"),"medium",("Jogeswar Singha",),"যোগেশ্বৰ সিংহ")

# ---------------------------------------------------------------- Ahom royal family
E("rajani","Rajani","Ahom queens and royal family",1324,1332,"early 14th century","Kamata princess, queen of Sukhaangphaa","Daughter of the Kamata king (Kamateswar), given with her sister Bhajani to Sukhaangphaa to seal a truce. Mother of Sukhrangphaa, Sutuphaa, Tyao Khamti and Tyao Chulai.","",("sukhaang","catalog"),"medium",("Rajani",),"ৰজনী",sort=1324)
E("bhajani","Bhajani","Ahom queens and royal family",1324,1332,"early 14th century","Kamata princess, queen of Sukhaangphaa","Rajani's sister, also given to Sukhaangphaa under the treaty; mother of Chao Pulai.","",("sukhaang",),"medium",sort=1325)
E("chao-pulai","Chao Pulai","Ahom queens and royal family",1330,1360,"14th century","Ahom prince","Son of Sukhaangphaa and Bhajani. The project catalogue shows him meeting Kamata envoys and being made governor of Sadiya.","Governor role comes from the catalogue only.",("sukhaang","catalog"),"low",("Chao Pulai","Prince Chao Pulai","Governor Chao Pulai","Infant Chao Pulai"),sort=1330)
E("joymoti","Joymoti Konwari","Ahom queens and royal family",1679,1680,"d. 1680","Ahom princess and wife of Gadadhar Singha","Wife of the prince who became king Gadadhar Singha. Tortured and killed by agents of Sulikphaa and Laluk Sola Borphukan while her husband hid in exile.","",("gadad","catalog"),"medium",("Joymoti","Princess Joymoti Konwari","Princess Joymoti"),"জয়মতী কোঁৱৰী",era="mughal")
E("ramani-gabharu","Ramani Gabharu","Ahom queens and royal family",1663,1663,"1663","Princess sent to the Mughals","Sent to the Mughal court under the 1663 Treaty of Ghilajharighat. Sources differ on whether she was Jayadhwaj Singha's daughter or Lachit's niece.","",("jayad","lachit"),"low",("Ramani Gabharu",),"ৰমণী গাভৰু")
E("pakhori-gabharu","Pakhori Gabharu","Ahom queens and royal family",1650,1680,"17th century","Queen, sister of Lachit Borphukan","Daughter of Momai Tamuli Borbarua and sister of Lachit; queen to Ahom kings.","",("lachit","ahomdyn"),"low",sort=1665)
E("phuleswari","Phuleswari (Pramatheswari)","Ahom queens and royal family",1722,1731,"Bar Raja 1722–1731","Queen who ruled as Bar Raja","A dancer of the Nat caste made Bar Raja under Siva Singha after astrologers predicted the king's fall. Minted coins in joint names and pressed to make Shaktism the state religion; died in 1731 in childbirth.","Her insult to the Moamoria Gosains is cited as a cause of the later rebellion.",("siva","ahomdyn"),"high",("Phuleswari","Queen Phuleswari (Bar Raja)"),"ফুলেশ্বৰী")
E("ambika","Ambika","Ahom queens and royal family",1732,1739,"Bar Raja 1732–1739","Queen who ruled as Bar Raja","Phuleswari's sister. Sponsored the Hastividyarnava and the Sivasagar Siva Doul.","Sources give her death as 1738 or the end of her reign as 1739.",("siva","ahomdyn"),"medium",("Ambika",),"অম্বিকা")
E("sarbeswari","Sarbeswari (Endari)","Ahom queens and royal family",1739,1744,"Bar Raja 1739–1744","Queen who ruled as Bar Raja","Held the same authority as her predecessors but was less active in patronising Shaktism.","",("siva","ahomdyn"),"medium",as_="সৰ্বেশ্বৰী")
E("kuranganayani","Kuranganayani","Ahom queens and royal family",1768,1770,"married 1768; active to 1770","Manipuri princess, queen of the Ahom kingdom","Married Rajeswar Singha in 1768 as thanks for Ahom help to her father. After his death she was taken by the rebel Ragha Moran and helped bring about his killing in April 1770; she later married Lakshmi Singha.","",("kuran","moam"),"high",("Kuranganayani",),"কুৰংগনয়নী")
E("numali-rajmao","Numali Rajmao","Ahom queens and royal family",1817,1818,"active 1817–1818","Queen-mother of Chandrakanta Singha","Reportedly behind the plot that led to the murder of Badan Chandra Borphukan.","",("burm","chandra"),"medium",("Mother Numali",),"নুমলী ৰাজমাউ")

# ---------------------------------------------------------------- Ahom officers
E("thaomung-burhagohain","First Burhagohain (Thaomung)","Ahom officers and generals",1228,1260,"c. 1228 (office created by Sukaphaa)","First Burhagohain","The Burhagohain and Borgohain offices were created by Sukaphaa. The personal names given in the project catalogue are unverified.","Name “Thaomung” comes from the project catalogue only.",("ahomk","catalog"),"low",("Thaomung Burhagohain",),sort=1229)
E("thaomung-borgohain","First Borgohain (Thaomung)","Ahom officers and generals",1228,1260,"c. 1228 (office created by Sukaphaa)","First Borgohain","See the first Burhagohain: the personal name is unverified.","",("ahomk","catalog"),"low",("Thaomung Borgohain",),sort=1230)
E("borgohain-khenphung","Khenphung Borgohain","Ahom officers and generals",1490,1493,"c. 1490","Borgohain","An Ahom Borgohain in the project catalogue, ambushed by the Tangshu Nagas.","",("catalog",),"low",("Borgohain Khenphung",),sort=1490)
E("konseng","Konseng Barpatragohain","Ahom officers and generals",1527,1539,"office created 1527","First Borpatragohain","Appointed the first Borpatragohain in 1527 by Suhungmung, the year the Ahoms defeated the first Muslim invasion.","",("suhung","catalog"),"medium",("Konseng Barpatragohain","Prince Konseng","Infant Konseng"),"কনচেং বৰপাত্ৰগোহাঁই")
E("ton-kham-borgohain","Ton Kham Borgohain","Ahom officers and generals",1532,1533,"1532–1533","Ahom general","Defeated Turbak's invasion and pursued the invaders to the Karatoya river.","",("ahomk","biswa"),"medium")
E("aikhek-burhagohain","Aikhek Burhagohain","Ahom officers and generals",1563,1563,"1563","Burhagohain","Offered little resistance to Chilarai's 1563 invasion and was removed as Burhagohain after the Treaty of Majuli.","",("sukhaam",),"medium")
E("momai-tamuli","Momai Tamuli Borbarua","Ahom officers and generals",1608,1663,"c. 1590–1663 (sources vary)","First Borbarua","Rose from humble origins to become the first Borbarua. Systematised the paik system in 1609, commanded at Duimunsila (1638) and signed the Treaty of Asurar Ali (1639). Father of Lachit Borphukan.","The infobox gives 1664 and a category gives 1650 for his death.",("momai","pratap"),"medium",("Momai Tamuli","Momai Tamuli Barbarua","First Borbarua Momai Tamuli"),"মোমাই তামুলী বৰবৰুৱা")
E("langi-panisiya","Langi Panisiya","Ahom officers and generals",1615,1625,"office created 1615 (catalogue)","First Borphukan","First holder of the Borphukan office, based at Kajali, created under Pratap Singha.","",("pratap","catalog"),"medium",("First Borphukan Langi Panisiya",))
E("parbatia-phukan","Manthir Bharali Barua (Parbatia Phukan)","Ahom officers and generals",1640,1650,"mid-17th century","Viceroy of western Assam","A Kayastha viceroy of western Assam whose appointment caused resentment among Ahom nobles.","",("amc",),"low",sort=1645)
E("atan-burhagohain","Atan Burhagohain","Ahom officers and generals",1662,1679,"Burhagohain 1662–1679","Burhagohain and Prime Minister","Appointed Burhagohain in January 1662 while Mir Jumla held Garhgaon. Negotiated the Treaty of Ghilajharighat, commanded the northern division at Saraighat and twice declined the crown. Murdered in 1679 by men of Laluk Sola Borphukan.","Served under eight kings.",("atan","amc"),"high",("Atan Burhagohain",),"অতন বুঢ়াগোহাঁই",death=1679)
E("lachit-borphukan","Lachit Borphukan","Ahom officers and generals",1667,1672,"1622–1672","Commander-in-chief and Borphukan","Retook Guwahati in 1667 and led the Ahom victory over a larger Mughal fleet at Saraighat in 1671. Died the next year, and his remains lie in a maidam at Jorhat.","Born 24 November 1622; died 25 April 1672 at Kaliabor. Fought at Alaboi in 1669.",("lachit","amc"),"high",("Lachit Borphukan",),"লাচিত বৰফুকন",birth=1622,death=1672)
E("laluk-sola","Laluk Sola Borphukan","Ahom officers and generals",1672,1680,"Borphukan 1672–1677; d. 1680","Borphukan","Elder brother of Lachit; succeeded him as Borphukan. Handed Guwahati to the Mughals in 1679 and was assassinated by his bodyguard in 1680.","Wikipedia dates his tenure 1672–1677 and his death 1680.",("laluk","amc"),"medium",("Laluk Sola Borphukan",),death=1680)
E("debera-borbarua","Debera Borbarua","Ahom officers and generals",1672,1675,"c. 1672–1675","Borbarua and king-maker","Dominated the court in the 1672–1675 succession struggle, setting up the short-lived kings Suhung and Gobar Roja.","From the project catalogue only; check against the Buranjis.",("catalog","ahomdyn"),"low",("Debera Borbarua",))
E("ghanashyam-khanikar","Ghanashyam Khanikar","Ahom officers and generals",1698,1705,"c. 1698–1705","Architect","Named in the project catalogue as the architect behind Rudra Singha's building of Rangpur.","Not found in the Rudra Singha article; treat as unverified.",("catalog",),"low",("Architect Ghanashyam",))
E("krishnaram-bhattacharya","Krishnaram Bhattacharya Nyayavagish","Ahom officers and generals",1696,1744,"early 18th century","Shakta adviser at court","A scholar from Nabadwip invited as religious guide under Rudra Singha; later adviser (Parbatiya Gosain) under Siva Singha.","",("rudra","ahomk"),"medium",("Parvatiya Gosain",))
E("niranjan-deva","Niranjan Deva (Niranjan Bapu)","Ahom officers and generals",1650,1663,"mid-17th century","Head of Auniati Satra","Initiated Jayadhwaj Singha and was made head of Auniati Satra.","",("jayad","catalog"),"medium",("Niranjan Deva of Auniati Satra",),sort=1652)
E("haranath-phukan","Haranath Bitarual Phukan","Ahom officers and generals",1765,1765,"1765","Ahom commander","Led the 1765 army sent to help Manipur against the Burmese; the jungle route defeated it and it became known as the War of the Creepers.","",("rajes","catalog"),"medium",("Haranath Senapati Phukan",))
E("kirti-chandra-borbarua","Kirti Chandra Borbarua (Gendhela)","Ahom officers and generals",1751,1769,"active 1751–1769","Borbarua and king-maker","Held real power under Rajeswar Singha and made Lakshmi Singha king in 1769. Had the Buranjis collected and many destroyed over references to his low origins.","",("rajes","laksh","ahomk"),"medium")
E("purnananda-burhagohain","Purnananda Burhagohain","Ahom officers and generals",1795,1817,"d. 27 March 1817","Burhagohain and Prime Minister","Placed Kamaleswar and then Chandrakanta on the throne and ran the state for two decades. Collapsed and died on 27 March 1817 on learning that Badan Chandra Borphukan was with the Burmese.","His eldest son Ruchinath succeeded him as Burhagohain.",("chandra","burm","gauri"),"high",("Purnananda Burhagohain",),"পূৰ্ণানন্দ বুঢ়াগোহাঁই",death=1817)
E("badan-chandra-borphukan","Badan Chandra Borphukan","Ahom officers and generals",1815,1818,"d. 1817–1818","Borphukan of Guwahati","Went to the Burmese court in 1816 seeking help against Purnananda Burhagohain and returned with an army in 1817. Assassinated by Subedar Rup Singh.","Sources give 1817 or 1818 for the assassination; the Wikipedia article gives 1818.",("badan","burm","chandra"),"medium",("Badan Chandra Borphukan",),"বদন চন্দ্ৰ বৰফুকন")
E("subedar-rup-singh","Subedar Rup Singh","Ahom officers and generals",1818,1818,"1818","Assassin of Badan Chandra","Killed Badan Chandra Borphukan, in a plot backed by the queen-mother.","",("badan","burm"),"medium",("Subedar Rup Singh",))
E("ruchinath-burhagohain","Ruchinath Burhagohain","Ahom officers and generals",1817,1822,"Burhagohain from 1817","Burhagohain","Eldest son of Purnananda; became Burhagohain in 1817, deposed Chandrakanta in February 1818 and installed Purandar Singha, and later sought British help.","",("chandra","purandar","burm"),"medium",("Ruchinath Burhagohain",))

# ---------------------------------------------------------------- Moamoria rebels
E("aniruddhadeva","Aniruddhadeva","Moamoria rebels",1553,1626,"1553–1626","Founder of the Moamara Satra","Vaishnava teacher who founded the Moamara satra, whose followers later led the Moamoria rebellion.","Dates from memory of standard accounts; verify.",(),"low",birth=1553,death=1626,era="bhakti",sort=1553)
E("mayamara-mahanta","Mayamara Mahanta","Moamoria rebels",1769,1769,"1769","Moamara abbot","Intervened to spare Lakshmi Singha's life when the rebels captured him in 1769.","",("laksh","moam"),"medium")
E("ragha-moran","Ragha Neog (Raghab Borbarua)","Moamoria rebels",1769,1770,"d. 11 April 1770","Rebel leader and Borbarua","Flogged over elephant levies in September 1769, which sparked the revolt. Became Borbarua and was killed in April 1770 by nobles aided by Kuranganayani.","",("moam","kuran"),"high",("Ragha Moran","Rebel Chief Ragha Moran"))
E("naharkhora","Naharkhora Saikia","Moamoria rebels",1769,1770,"d. 1770","Rebel leader","Co-leader with Ragha; helped install his son Ramakanta as rebel king and was executed in the 1770 purge.","",("moam",),"high",("Naharkhora",))
E("ramakanta","Ramakanta","Moamoria rebels",1769,1770,"Nov 1769 – 1770","Rebel king","Naharkhora's son, placed on the throne by the rebels in November 1769 and executed in 1770.","",("moam",),"high",("Ramakanta",))
E("harihar-tanti","Harihar Tanti","Moamoria rebels",1786,1786,"1786","Rebel organiser","Reorganised the Dafla-Bhatia rebels in 1786 and administered the north bank of the Brahmaputra.","",("moam",),"medium")
E("bharat-singha","Bharat Singha","Moamoria rebels",1786,1799,"d. 1799","Rebel king","Moamoria chief placed on the throne after the 1785–86 rebel victory; coins were struck in his name. Killed in 1799 (another page gives 1800).","",("moam","ahomk"),"medium")
E("sarbananda-singha","Sarbananda Singha","Moamoria rebels",1795,1805,"to 1805","Rebel ruler of the Moran tracts","Ruled the Moran tracts from Bengmara. After fighting royalists in 1805 he accepted peace, became Barsenapati and governed the autonomous Matak kingdom.","",("moam",),"medium")
E("krishnanarayan","Krishnanarayan (Darrang rebel)","Moamoria rebels",1791,1792,"1791–1792","Rebel prince of Darrang","Rebelled in Darrang in 1791 and occupied North Guwahati with Haradatta; defeated by Captain Welsh in 1792.","",("gauri","moam"),"medium")

# ---------------------------------------------------------------- Koch
E("biswa-singha","Biswa Singha","Koch kingdom",1515,1540,"r. 1515–1540","Founder of the Koch dynasty","Son of Hariya Mandal and Hira. Defeated the Baro-Bhuyans and founded the Koch kingdom in Kamata; his sons Nara Narayan and Chilarai followed.","Campaigns began c. 1509; coronation 1515. Sources differ on the cause of death.",("biswa","koch"),"high",("Biswa Singha",),"বিশ্ব সিংহ")
E("nara-narayan","Nara Narayan","Koch kingdom",1540,1587,"r. 1540–1587","Second Koch king","Took the Koch kingdom to its peak with his brother Chilarai as commander. Introduced the Narayani silver coin; Sankardev's teaching spread in his time.","Infobox gives 1554–1587; text gives 1540. Died 1587 (some sources 1588).",("nara","koch"),"high",("Naranarayan",),"নৰনাৰায়ণ")
E("chilarai","Chilarai (Sukladhwaj)","Koch kingdom",1540,1571,"1510–1571","Koch general","Third son of Biswa Singha and commander-in-chief under Nara Narayan. Led the 1562–63 invasion that forced the Treaty of Majuli; died of smallpox in 1571.","Spouse: Kamalpriya.",("chilarai","sukhaam","koch"),"high",("General Chilarai","Chilarai"),"চিলাৰায়",birth=1510,death=1571)
E("gosain-kamal","Gosain Kamal (Kamal Narayan)","Koch kingdom",1540,1580,"16th century","Koch prince and governor","Step-brother of Nara Narayan; built the Gohain Kamal Ali road and governed Khaspur.","",("nara","koch"),"medium")
E("raghudev","Raghudev","Koch kingdom",1581,1603,"c. 1581–1603","Koch Hajo ruler","Son of Chilarai; made himself independent in the east after Nara Narayan's death, dividing the kingdom for good.","",("koch","nara"),"medium")
E("lakshmi-narayan","Lakshmi Narayan","Koch kingdom",1587,1621,"c. 1587–1621","Koch Bihar king","Son of Nara Narayan who kept only Koch Bihar; allied with the Mughals in 1612 against Parikshit Narayan.","",("koch","nara"),"medium")
E("parikshit-narayan","Parikshit Narayan","Koch kingdom",1603,1612,"to 1612","Koch Hajo king","Attacked by the Mughals and Lakshmi Narayan in 1612 and taken to Delhi. His daughter Mangaldahi married Pratap Singha in 1608.","",("koch","pratap"),"medium",era="mughal")
E("balinarayan","Balinarayan","Koch kingdom",1615,1640,"from 1615","Founder of Darrang","Brother of Parikshit; installed by Pratap Singha as vassal of Darrang after the Mughals were repelled in 1615.","",("koch",),"medium")

# ---------------------------------------------------------------- Kamata and Khen
E("durlabhnarayan","Durlabhnarayan (Kamata)","Kamata and Khen kingdoms",1305,1335,"early 14th century","King of Kamata","Son of Pratapdhwaj who took Kamrup, Goalpara and Koch Bihar from Kamatapur. His court poets produced early Assamese literature, including Hema Saraswati and Harihara Vipra.","The catalogue places him in the Ahom–Kamata wars of the early 14th century.",("kamata","hema","catalog"),"medium",("Durlabhanarayana","Kamata Raja Durlabhanarayana"),"দুৰ্লভনাৰায়ণ")
E("indranarayan","Indranarayan","Kamata and Khen kingdoms",1357,1390,"late 14th century","King of Kamata","Weakened by Sikandar Shah's invasion, which let a Bhuyan take power.","",("kamata",),"low",sort=1360)
E("arimatta","Arimatta (Sasanka)","Kamata and Khen kingdoms",1390,1420,"c. 15th century","Bhuyan usurper","A Bhuyan of Darrang who killed Indranarayan and took the Kamata throne.","",("kamata",),"low",sort=1395)
E("mriganka","Mriganka (Jungal Balahu)","Kamata and Khen kingdoms",1420,1440,"15th century","Last Bhuyan king of Kamata","Removed by the Khen dynasty.","",("kamata",),"low",sort=1425)
E("niladhwaj","Niladhwaj","Kamata and Khen kingdoms",1440,1460,"mid-15th century","First Khen king","United several Baro-Bhuyan chieftains and removed Mriganka.","",("kamata",),"medium",sort=1440)
E("chakradhwaj-khen","Chakradhwaj (Khen)","Kamata and Khen kingdoms",1460,1480,"15th century","Second Khen king","Second ruler of the Khen dynasty; no dates or events are given.","",("kamata",),"low",sort=1460)
E("nilambar","Nilambar","Kamata and Khen kingdoms",1480,1498,"to c. 1498","Last Khen king","Expanded Kamata to Kamrup and the Karatoya and built forts, but was defeated after a long siege by Alauddin Husain Shah's general around 1498–99.","",("kamata","husain"),"high")
E("alauddin-husain-shah","Alauddin Husain Shah","Sultanate and Mughal figures",1493,1519,"r. 1493–1519","Sultan of Bengal","Founder of the Hussain Shahi dynasty; his general Shah Ismail Ghazi defeated Nilambar and annexed Kamatapur and Kamrup up to Hajo. His son Danyal was made viceregent.","The Baro-Bhuyans later killed Danyal and ended Sultanate rule.",("husain","kamata"),"high")

# ---------------------------------------------------------------- Chutia
E("satyanarayana-chutia","Satyanarayana (Ratnanarayana)","Chutia kingdom",1380,1400,"late 14th century","Chutia king","One of the earliest attested Chutia kings, ruling from Sadhayapuri (Sadiya); a grant is dated 1392.","",("chutia",),"medium")
E("lakshminarayana-chutia","Lakshminarayana (Dharmanarayana)","Chutia kingdom",1400,1428,"early 15th century","Chutia king","Chutia king known from sources dated 1392 and 1401.","",("chutia",),"medium",sort=1405)
E("durlabhnarayana-chutia","Durlabhnarayana (Chutia)","Chutia kingdom",1428,1442,"early 15th century","Chutia king","Chutia king known from a grant dated 1428.","Not the Kamata king of the same name.",("chutia",),"medium",sort=1428)
E("muktadharmanarayana","Muktadharmanarayana","Chutia kingdom",1442,1460,"mid-15th century","Chutia king","Known from an inscription dated 1442.","",("chutia",),"medium",sort=1442)
E("dhirnarayan","Dhirnarayan","Chutia kingdom",1510,1523,"to 1523–24","Last Chutia king","Built a fort at Dikhowmukh in 1513, was routed attacking the Ahom fort at Dibru in 1523, and was killed, ending the kingdom in 1523–24.","Known from an inscription dated 1522.",("chutia","suhung"),"high",("Dhirnarayan",))

# ---------------------------------------------------------------- Dimasa (Kachari)
E("khorapha","Khorapha","Dimasa (Kachari) kingdom",1520,1526,"c. 1520–1526","Dimasa king","Issued a silver coin in 1520 and was killed in an Ahom attack in 1526.","",("dimasa",),"medium")
E("khunkhara","Khunkhara","Dimasa (Kachari) kingdom",1526,1531,"1526–1531","Dimasa king","Succeeded his brother Khorapha and fled Dimapur when the Ahoms attacked in 1531.","",("dimasa","kachari"),"medium")
E("detsung","Detsung (Dersung)","Dimasa (Kachari) kingdom",1531,1536,"1531–1536","Dimasa king","Installed by Suhungmung, to whom he gave his sister in marriage; killed when he tried to break free. The Ahoms occupied Dimapur in 1536.","",("dimasa","kachari"),"medium")
E("yasho-narayan","Yasho Narayan (Satrudaman)","Dimasa (Kachari) kingdom",1583,1601,"c. 1583–1601","Most powerful Dimasa king","Ruled North Cachar, the Dhansiri valley and parts of Sylhet and struck coins in his name.","",("dimasa","kachari"),"medium")
E("tamradhwaj","Tamradhwaj Narayan","Dimasa (Kachari) kingdom",1706,1708,"1706–1708","Dimasa king","Declared independence; Rudra Singha invaded Maibong in December 1706 and destroyed its fort. Tamradhwaj fled to Jaintia and was imprisoned.","",("dimasa","rudra","kachari"),"high",("Kachari King Tamradhwaj",))
E("krishnachandra","Krishnachandra Narayan","Dimasa (Kachari) kingdom",1790,1813,"1790–1813","Dimasa king","Sheltered Moamoria rebels, causing Ahom–Dimasa skirmishes from 1803 to 1805; helped Manipur against the Burmese.","",("dimasa","moam"),"medium")
E("govindachandra","Govindachandra Narayan","Dimasa (Kachari) kingdom",1814,1830,"1814–1830","Last Dimasa king","Restored by the British after the 1826 Treaty of Yandabo; died in 1830.","The two sources split his reign into two periods.",("dimasa","kachari"),"medium")

# ---------------------------------------------------------------- Jaintia and Manipur
E("jasa-manik","Jasa Manik","Jaintia and Manipur",1612,1625,"1612–1625","Jaintia king","Jaintia king whose manoeuvres are linked to the Dimasa–Ahom conflict of 1618.","",("jaintia","dimasa"),"medium")
E("ram-singh-jaintia","Ram Singh I (Jaintia)","Jaintia and Manipur",1694,1708,"1694–1708","Jaintia king","Kidnapped the Dimasa king, prompting Rudra Singha's 1707–08 invasion; died an Ahom captive.","",("jaintia","rudra"),"high",("Jaintia King Ram Singha",))
E("ram-singh-ii-jaintia","Ram Singh II (Jaintia)","Jaintia and Manipur",1790,1832,"1790–1832","Jaintia king","Long-reigning Jaintia king who agreed in 1824 to deal only with the British.","",("jaintia",),"medium")
E("bhagyachandra","Bhagyachandra (Jai Singh)","Jaintia and Manipur",1759,1798,"1748–1798","King of Manipur","Fled to Ahom territory after the Burmese invasion of 1764 and was sheltered by Rajeswar Singha, who backed his return; reinstated in 1773. Promoted Vaishnavism and the Manipuri Raas Leela.","",("bhagya","rajes"),"high",("Jai Singh","Manipur King Jai Singh"))
E("gambhir-singha","Gambhir Singha","Jaintia and Manipur",1825,1825,"1825","King of Manipur","Repulsed the Burmese in 1825.","",("burm",),"medium")

# ---------------------------------------------------------------- Bhakti and poets
E("hema-saraswati","Hema Saraswati","Poets and writers",1280,1330,"13th–14th century (uncertain)","Court poet of Kamata","Counted among the first known Assamese writers, patron Durlabhnarayan. His Prahlada Charita is regarded as the earliest known Assamese poem.","No explicit dates in the source.",("hema",),"low",as_="হেম সৰস্বতী",sort=1300)
E("harihara-vipra","Harihara Vipra","Poets and writers",1300,1350,"14th century","Court poet of Kamata","Pre-Vaishnava Assamese poet; wrote Babruvahanar Yuddha.","Century from a category tag only.",("harihara",),"low",as_="হৰিহৰ বিপ্ৰ",sort=1310)
