EVENTS = []
def V(year, end, title, body, ids=(), src=()):
    EVENTS.append(dict(year=year, end=end, title=title, body=body, ids=list(ids), sources=[SRC[x] for x in src]))
V(1100,None,"The Pala line of Kamarupa ends","Jaya Pala is the last known king of the Pala line. The name Kamarupa fades over the next century as the old kingdom breaks into regions (the end is variously dated 1100, 1140 or the 13th century).",("jaya-pala",),("kamarupa","palakam"))
V(1110,1140,"Bengal's Palas take western Kamarupa","Ramapala conquers the west and puts Timgyadeva in charge (c. 1110–1126). Vaidyadeva follows (c. 1126–1140) and in effect founds a separate kingdom after Kumarapala's death.",("ramapala","timgyadeva","kumarapala-bengal","vaidyadeva"),("palakam","kamarupa"))
V(1120,1200,"A “lunar dynasty” on the north bank","Bhaskara, Rayarideva, Udayakarna and Vallabhadeva hold parts of Kamrup, Darrang and Sonitpur. They are known from a single 1185 inscription.",("bhaskara-lunar","rayarideva","udayakarna","vallabhadeva"),("kamarupa",))
V(1205,1206,"Bakhtiyar Khalji's army is destroyed","On his way back from a failed Tibet campaign, Bakhtiyar's army is annihilated in Kamarupa. The king who defeated him is traditionally called Prithu, but that identification is disputed.",("bakhtiyar-khalji","prithu"),("mik","prithu"))
V(1226,1228,"Iwaz Khalji and Nasiruddin Mahmud","Ghiyasuddin Iwaz Khalji invades and withdraws; he is captured and killed in 1227–28. Nasiruddin Mahmud installs a tributary king in Kamarupa who loses control after 1229.",("ghiyasuddin-iwaz-khalji","nasiruddin-mahmud","prithu"),("mik","kamarupa"))
V(1228,None,"Sukaphaa reaches Assam","After leaving Mong Mao in 1215, Sukaphaa arrives at Namrup in December 1228. The Ahom kingdom is dated from here. In the west, Sandhya takes the throne of Kamarupa in the same year.",("sukaphaa","sandhya"),("sukapha","sandhya"))
V(1257,None,"Yuzbak is defeated; Kamata takes shape","Ikhtiyaruddin Yuzbak, governor of Bengal, invades and is defeated and killed or captured by Sandhya. Sandhya moves the capital to Kamatapur, founding the Kamata kingdom.",("ikhtiyaruddin-yuzbak","sandhya"),("yuzbak","sandhya"))
V(1321,1322,"Bahadur Shah raids Kamata","Ghiyasuddin Bahadur Shah of Sonargaon raids as far as Nagaon, meeting ineffective resistance from Pratapdhwaj and the Kacharis, but keeps no territory.",("ghiyasuddin-bahadur-shah","pratapdhwaj"),("mik",))
V(1324,None,"The first Ahom–Kamata war","A long war between Sukhaangphaa and the Kamata king ends in a truce. It is sealed by Sukhaangphaa's marriage to the Kamata princesses Rajani and Bhajani.",("sukhaangphaa","rajani","bhajani"),("sukhaang",))
V(1330,1370,"Mahamanikya and the Saptakanda Ramayana","The Barahi king Mahamanikya rules around Nagaon and Hojai (a 1352 inscription records his grant) and sponsors Madhava Kandali's Ramayana.",("mahamanikya","madhava-kandali"),("mahamanikya","mkandali"))
V(1330,1350,"Durlabhnarayan's court poets","Under Durlabhnarayan of Kamata, poets such as Hema Saraswati and Harihara Vipra write some of the earliest Assamese literature.",("durlabhnarayan","hema-saraswati","harihara-vipra"),("kamata","hema","harihara"))
V(1356,1362,"Ilyas Shah and Sikandar Shah invade","Bengal forces occupy Kamrup including Guwahati in 1356–57. Sikandar Shah then pushes to the Kopili, where Kamata, Bhuyan and Barahi forces fight him near Gachtal. A coin of 1360 carries a Kamrup mint name.",("shamsuddin-ilyas-shah","sikandar-shah-bengal","indranarayan","mahamanikya"),("mik","bkw","mahamanikya"))
V(1380,1400,"The Chutia kingdom appears in the record","Nandi and Satyanarayana rule from Sadhayapura (Sadiya), the earliest Chutia kings known from inscriptions. Tyao Khamti's expedition against them fails (1380–87).",("nandi-chutia","satyanarayana-chutia","tyao-khamti"),("chutia",))
V(1364,1397,"Interregnums in the Ahom kingdom","Three Ahom kings are assassinated or die, and the throne stays empty for long stretches (1364–1369, 1376–1380, 1389–1397).",("sukhrangphaa","sutuphaa","tyao-khamti"),("ahomdyn",))
V(1397,1407,"Sudangphaa restores the Ahom throne","The prince raised by a Brahmin family in Habung is found and enthroned in 1397. A 1401 treaty fixes the Patkai boundary and in 1403 the capital moves to Charguwa.",("sudangphaa","chaothai-khum-burhagohain","thao-cheoken"),("sudang",))
V(1396,1400,"Kamata and the Ahoms drive back Azam Shah","The Kamata king, allied with Sudangphaa by marriage, expels Ghiyasuddin Azam Shah across the Karatoya. A Boko inscription shows the Sultanate held part of Kamrup for some years.",("ghiyasuddin-azam-shah","sudangphaa"),("mik",))
V(1365,1440,"Bhuyan rule in Kamata","After Indranarayan, the Bhuyan Arimatta seizes the throne, followed by Gajanka, Sukranka and Mriganka (dates are reconstructed).",("arimatta","gajanka","sukranka","mriganka"),("kamata","keralakam"))
V(1440,1498,"The Khen dynasty","Niladhwaj (1440–1460), Chakradhwaj (1460–1480) and Nilambar (1480–1498) rule from Kamatapur. Nilambar expands the kingdom into Kamrup and Darrang.",("niladhwaj","chakradhwaj-khen","nilambar"),("khen","nilambar","niladhwaj","chakrakh"))
V(1488,1497,"Two Ahom kings in quick succession","Suhenphaa is speared to death in his palace in 1493; Supimphaa rules until 1497, when Suhungmung takes the throne.",("suhenphaa","supimphaa","suhungmung"),("ahomdyn",))
V(1492,1493,"Muzaffar Shah takes parts of Kamata","The Bengal sultan conquers part of Kamata and issues coins with the title Kamata Mardan.",("shamsuddin-muzaffar-shah",),("khen",))
V(1498,1502,"Husain Shah conquers Kamata","Shah Ismail Ghazi besieges and destroys Kamatapur and captures Nilambar, ending the Khen dynasty. The Sultanate holds land up to Hajo by 1502. Dates of the conquest vary between 1498 and 1499.",("alauddin-husain-shah","shah-ismail-ghazi","nilambar","sachipatra"),("bkw","nilambar","husain"))
V(1502,1515,"The Bhuyans end Sultanate rule","Under Harup Narayan the Assamese Bhuyans overrun Danyal's garrison about ten years after the conquest. Rule passes to the Bhuyans until the Koch rise.",("danyal","harup-narayan"),("bkw","baro"))
V(1512,1524,"Suhungmung annexes the Chutia kingdom","Habung is taken in 1512 and Dhirnarayan is routed at Dibru in 1523. By 1524 Phrasengmung Borgohain governs Sadiya.",("suhungmung","dhirnarayan","phrasengmung-borgohain"),("suhung","chutia"))
V(1515,None,"Biswa Singha founds the Koch kingdom","Biswa Singha is crowned in Kamata after defeating the Baro-Bhuyans, ending the confusing interval of fragments left after the Khen.",("biswa-singha",),("biswa","koch"))
(ROOT / "data/research").mkdir(parents=True, exist_ok=True)
(ROOT / "data/research/events_1100_1515.json").write_text(json.dumps(dict(schema="ahom-events-v1", events=EVENTS), ensure_ascii=False, indent=1), encoding="utf-8")
print(len(EVENTS), "events")

